 1	/**
 2	 * Scoped to this atom's own contract per testing.md: given a formatted string or nothing, does
 3	 * it render the right branch, and does the price it renders stay announceable.
 4	 *
 5	 * Formatting is deliberately not asserted here — it happens at the page
 6	 * (`selectPdpProductInfo`, proven in pages/product-detail/productInfo.test.ts) and this atom
 7	 * renders whatever string it is handed. What is not proven anywhere else is the absent branch:
 8	 * the mapper resolves a missing price to `''`, so the empty case is a real production path and
 9	 * not a defensive edge case.
10	 */
11	import React from 'react';
12	import { describe, test, expect } from 'vitest';
13	import { render, screen } from '@testing-library/react';
14	import { ZimmProductPrice } from './index';
15	
16	describe('ZimmProductPrice', () => {
17	  test('renders the caller-formatted string verbatim', () => {
18	    render(<ZimmProductPrice currentPrice="HK$6,200.00" />);
19	    // Verbatim, not re-formatted: the currency symbol, grouping and decimals are all the
20	    // page's decisions, and re-deriving any of them here would diverge per storefront.
21	    expect(screen.getByTestId('product-price').textContent).toBe('HK$6,200.00');
22	  });
23	
24	  test('announces the price through a polite atomic live region', () => {
25	    const { container } = render(<ZimmProductPrice currentPrice="HK$6,200.00" />);
26	
27	    // A variant change swaps this string with no focus move, so WCAG 2.2 AA 4.1.3 needs the
28	    // update announced. Both attributes are asserted: dropping `aria-atomic` would let a screen
29	    // reader announce only the characters that differ instead of the whole price, and neither
30	    // loss shows up on screen, so nothing else would catch it.
31	    const price = screen.getByTestId('product-price');
32	    expect(price).toHaveAttribute('aria-live', 'polite');
33	    expect(price).toHaveAttribute('aria-atomic', 'true');
34	
35	    // The live region is the price element itself, not an extra hidden twin. Asserted because
36	    // the single-node shape is load-bearing, not incidental: `ZimmProductContent` renders this
37	    // atom into a flex column whose own `play` tests assert that column's exact child count, so
38	    // a second node here fails them from another folder.
39	    expect(container.querySelectorAll('[aria-live]')).toHaveLength(1);
40	    expect(container.firstChild).toBe(price);
41	  });
42	
43	  // PRC-09 — Was/Now sale treatment
44	  test('renders Was and Now spans when originalPrice is supplied', () => {
45	    render(<ZimmProductPrice currentPrice="$450.00" originalPrice="$595.00" />);
46	
47	    expect(screen.getByTestId('product-was-price')).toHaveTextContent('Was $595.00');
48	    expect(screen.getByTestId('product-now-price')).toHaveTextContent('Now $450.00');
49	  });
50	
51	  test('renders only the standard price when originalPrice is absent', () => {
52	    render(<ZimmProductPrice currentPrice="$595.00" />);
53	
54	    expect(screen.queryByTestId('product-was-price')).not.toBeInTheDocument();
55	    expect(screen.queryByTestId('product-now-price')).not.toBeInTheDocument();
56	    expect(screen.getByTestId('product-price')).toHaveTextContent('$595.00');
57	  });
58	
59	  test('live region remains a single element in the sale variant', () => {
60	    // The live region must still be exactly one node (the chakra.p), even though its children
61	    // change. Two nodes would let ZimmProductContent's play tests break (child-count assertions).
62	    const { container } = render(<ZimmProductPrice currentPrice="$450.00" originalPrice="$595.00" />);
63	    expect(container.querySelectorAll('[aria-live]')).toHaveLength(1);
64	  });
65	
66	  // CodeRabbit a11y fix: live region must stay in the AT tree during loading so the
67	  // price announcement fires when the fetch settles.
68	  test('live region stays in the AT and preserves element identity across the loading transition', () => {
69	    const { rerender } = render(<ZimmProductPrice isLoading={true} currentPrice="$450.00" originalPrice="$595.00" />);
70	
71	    const region = screen.getByTestId('product-price');
72	    // aria-hidden absence is required but not sufficient — visibility:hidden also removes the
73	    // element from the AT. opacity:0 is the correct visual-hiding technique here.
74	    expect(region).not.toHaveAttribute('aria-hidden');
75	    expect(region).not.toHaveStyle({ visibility: 'hidden' });
76	    expect(region).toHaveAttribute('aria-live', 'polite');
77	
78	    // Same DOM node after loading resolves — React reuses the chakra.p at the same position
79	    // so the AT's registered live region is preserved and announces the price on settle.
80	    rerender(<ZimmProductPrice isLoading={false} currentPrice="$450.00" originalPrice="$595.00" />);
81	    expect(screen.getByTestId('product-price')).toBe(region);
82	    expect(screen.getByTestId('product-was-price')).toHaveTextContent('Was $595.00');
83	    expect(screen.getByTestId('product-now-price')).toHaveTextContent('Now $450.00');
84	  });
85	
86	  test.each([undefined, ''])('renders nothing for %s', (currentPrice) => {
87	    const { container } = render(<ZimmProductPrice currentPrice={currentPrice} />);
88	    // `''` is what the page's mapper produces for a product with no price, so this branch is
89	    // reached in production. An empty styled node would still consume a gap in
90	    // ZimmProductContent's flex column, leaving a visible hole between name and description.
91	    //
92	    // Asserted as an empty container rather than an absent testid: a node that still carried the
93	    // recipe's styling but had lost its `data-testid` would satisfy the narrower check while
94	    // being precisely the gap-consuming element this guard exists to prevent.
95	    expect(container).toBeEmptyDOMElement();
96	  });
97	});

