  test('component overrides are registered', () => {
    // ListMenu in particular: the base component reads
    // theme.components.ListMenu.baseStyle directly, so a missing entry throws
    // at render rather than falling back.
    expect(theme.components.Button).toBeTruthy();
    expect(theme.components.Header).toBeTruthy();
    expect(theme.components.ListMenu).toBeTruthy();

    // The opposite failure mode, and the reason this list stays hand-maintained rather than
    // derived from the `components` map — a derived list moves with any unregistration and so
    // could never catch one. Where ListMenu throws, all seven below fail silently:
    // `useStyleConfig` and `useMultiStyleConfig` return an empty object for an unregistered
    // recipe, `__css={undefined}` is a legal prop, and the element quietly inherits instead.
    //
    // An unregistration now costs more than it used to: this batch moved `textStyle` off the JSX
    // elements and into these recipes, so all type goes with the registration, not just colour
    // and box metrics. What else goes varies — the three single-part atoms (ZimmProductName,
    // ZimmProductModelInfo, ZimmProductPrice) carry only `margin: 0`, one colour and a
    // `textStyle`, and ZimmProductPrice's sole `variants` entry is empty; ZimmProductDescription
    // adds `& > *` block rhythm and the `ul`/`ol` indent that keeps its `disc` markers inside the
    // info column; ZimmProductStyleCode is multipart (`root`/`label`/`value`) — a flex row, a 4px
    // gap and the quieter `text-secondary` colour; and ZimmProductMeta and ZimmProductContent are
    // the two molecules' flex columns, whose 28px and 20px rhythms collapse to zero without them.
    //
    // The colour is the part no visual review catches: the base template's own `styles.js` sets
    // `color: 'gray.900'` on the body, and the gray scale in play is SFCC's, not Chakra's — its
    // `foundations/colors.js` replaces the whole scale before our overrides merge. SFCC's
    // `gray.900` is #181818 against the brand's #191919, one unit per channel.
    //
    // Scope, stated precisely because it is narrower than it looks: `toBeTruthy()` catches an
    // *unregistration* — the entry going missing from the map — and nothing else. A recipe still
    // exported but emptied to `{}` is truthy and passes all seven while losing every style.
    //
    // Only three pin a resolved value anywhere: ZimmProductMeta in its own suite,
    // ZimmProductDescription and ZimmProductContent in a story `play`. ZimmProductName,
    // ZimmProductModelInfo, ZimmProductStyleCode and ZimmProductPrice assert structure, text and
    // ARIA but never a computed value, so for those four a gutted-but-registered recipe is caught
    // by nothing here or elsewhere. That is a known gap, not something these lines cover — and it
    // matters more since type moved off the elements into these recipes.
    expect(theme.components.ZimmProductMeta).toBeTruthy();
    expect(theme.components.ZimmProductName).toBeTruthy();
    expect(theme.components.ZimmProductModelInfo).toBeTruthy();
    expect(theme.components.ZimmProductPrice).toBeTruthy();
    expect(theme.components.ZimmProductDescription).toBeTruthy();
    expect(theme.components.ZimmProductStyleCode).toBeTruthy();
    expect(theme.components.ZimmProductContent).toBeTruthy();
  });
});

describe('scale token collisions — Chakra keeps its own meanings', () => {
  test('fontSizes are NOT remapped to the Zimmermann scale', () => {
    // Design system: md 24px, xs 16px, 2xs 14px, 3xs 12px, 4xs 10px.
    // Chakra: md 16px, xs 12px, 2xs 10px, 3xs 7.2px — four collisions.
    // Type is set via `textStyle`, never a raw `fontSize` token, precisely so
    // these two scales never have to agree. If this test fails, someone has
    // remapped the scale and every base-component `fontSize` shifted with it.
    expect(theme.fontSizes.md).toBe('1rem');
    expect(theme.fontSizes.xs).toBe('0.75rem');
    expect(theme.fontSizes['2xs']).toBe('0.625rem');
  });

